const types=[["duck","warm ivory domestic duck and fluffy yellow duckling with broad orange bill"],["cow","warm brown dairy cow and calf, small calf horns absent"],["sheep","cream woolly sheep and lamb, lamb has short tight fleece"],["pig","dusty rose domestic pig and round short snouted piglet"],["goat","cream tan goat and kid, adult small swept horns and beard, kid no large horns"],["rabbit","warm grey cream rabbit and baby rabbit with round head and short ears"],["cat","cream ginger adult farm cat"],["dog","tan brown adult farm dog with floppy ears"]];
await Promise.allSettled(types.map(async ([key,subject])=>{
 const young=!["cat","dog"].includes(key);
 const r=await tools.image_gen__imagegen({transparent_background:true,prompt:`Production sprite COMPONENT atlas for a 2D painted Chinese pastoral game. ${subject}. Transparent RGBA outside, no colored fringe or opaque background, no text/shadows/grids. Exactly 6 equal columns and ${young?8:4} equal rows. Rows top to bottom ${young?"ADULT front, ADULT facing LEFT (nose points left), ADULT facing RIGHT (nose right), ADULT back; then YOUNG front, YOUNG facing LEFT, YOUNG facing RIGHT, YOUNG back":"front, facing LEFT (nose left), facing RIGHT (nose right), back"}. Each cell contains ONE separated component centered, full padding. Columns always: 1 torso without head or legs; 2 head WITH ears eyes muzzle neck; 3 one front leg with paw or hoof; 4 one rear leg with paw or hoof; 5 tail; 6 same head eyes CLOSED for blink. For duck column3 one wing and column4 one leg with webbed foot. Paint complete opaque filled body pieces including hidden overlap areas, not cropped holes. Fine pencil and soft gouache, anatomically believable animal, cozy realistic painted volume and warm top-left light, muted earth colors. Components share a consistent scale for each age. Adult torso width180 and height120, head95, legs90, tail80 pixels. ${young?"Young is independently designed, rounder body120, large head100, shorter legs45, soft juvenile fur; not merely a scaled adult.":""} All parts isolated clearly from neighbors. No full assembled animals. Four explicit consistent views. Balanced precise sprite sheet layout, no extra components or scene.`});
 store("ranch_generated_"+key,{output_hint:r.output_hint});
 text({species:key,output_hint:r.output_hint});
}));
